export const meta = {
  "slug": "phosphor-arrow-clockwise",
  "family": "phosphor",
  "name": "arrow-clockwise",
  "category": "Navigation",
  "motion": "spin",
  "component": "createPhosphorArrowClockwiseIcon"
};

export function createPhosphorArrowClockwiseIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
